  "ls.mediated_note": { pt: "🛡️ As mensagens vão diretamente à outra pessoa. Não são entregues mensagens com telefones, e-mails, WhatsApp, redes sociais, ligações ou contas bancárias: combine tudo aqui e pague com o pagamento protegido. Fotografias, áudios, vídeos e documentos passam primeiro pela equipa.", en: "🛡️ Messages go directly to the other person. Messages with phone numbers, e-mails, WhatsApp, social media, links or bank accounts are not delivered: arrange everything here and pay with protected payment. Photos, audio, videos and documents go through the team first.", zh: "🛡️ 消息直接发送给对方。含有电话、电子邮件、WhatsApp、社交网络、链接或银行账户的消息不会送达：请在这里沟通，并使用担保支付付款。照片、语音、视频和文件会先经过团队审核。", fr: "🛡️ Les messages vont directement à l'autre personne. Les messages contenant des téléphones, e-mails, WhatsApp, réseaux sociaux, liens ou comptes bancaires ne sont pas remis : organisez tout ici et payez avec le paiement protégé. Les photos, audios, vidéos et documents passent d'abord par l'équipe." },
  "ls.msg_blocked": { pt: "🚫 Não entregue: tinha contactos ou dados bancários", en: "🚫 Not delivered: it contained contact or bank details", zh: "🚫 未送达：包含联系方式或银行信息", fr: "🚫 Non remis : contenait des coordonnées ou des données bancaires" },
  "ls.msg_pending": { pt: "⏳ A equipa revê antes de entregar", en: "⏳ The team reviews it before delivery", zh: "⏳ 团队审核后再送达", fr: "⏳ L'équipe le vérifie avant de le remettre" },
