  "ls.rent_free_note": { pt: "Arrendamento de imóveis é grátis: sem custos nem comissões.", en: "Property rentals are free: no fees or commissions.", zh: "房产出租免费：无任何费用或佣金。", fr: "La location de biens immobiliers est gratuite : ni frais ni commissions." },
