  "ls.ai.hint": { pt: "A IA reescreve o título e a descrição com o que escreveu (não inventa nada). Reveja antes de publicar.", en: "AI rewrites the title and description from what you wrote (it doesn't invent anything). Review before publishing.", zh: "AI 会根据您写的内容重写标题和描述（不会编造）。发布前请检查。", fr: "L'IA réécrit le titre et la description à partir de ce que vous avez écrit (elle n'invente rien). Relisez avant de publier." },
  "ls.ai.done": { pt: "Texto melhorado. Reveja e ajuste se for preciso. Restam {n} hoje.", en: "Text improved. Review and adjust if needed. {n} left today.", zh: "文字已优化。如有需要请检查并调整。今天还剩 {n} 次。", fr: "Texte amélioré. Relisez et ajustez si nécessaire. Il en reste {n} aujourd'hui." },
  "ls.ai.undo": { pt: "↩️ Voltar ao meu texto", en: "↩️ Back to my text", zh: "↩️ 恢复我的文字", fr: "↩️ Revenir à mon texte" },
  "em.unsub.title": { pt: "Cancelar os emails", en: "Unsubscribe from emails", zh: "取消邮件", fr: "Se désabonner des e-mails" },
  "em.unsub.text": { pt: "Deixa de receber o resumo diário das notificações por email. Os avisos continuam no Site e na APP.", en: "You'll stop getting the daily notification summary by email. Notices stay on the Site and the APP.", zh: "您将不再通过邮件收到每日通知摘要。通知仍会显示在网站和 APP 中。", fr: "Vous ne recevrez plus le résumé quotidien des notifications par e-mail. Les avis restent sur le Site et l'APP." },
  "em.unsub.button": { pt: "Cancelar os emails", en: "Unsubscribe", zh: "取消邮件", fr: "Se désabonner" },
  "em.unsub.done": { pt: "Pronto: já não vai receber estes emails. Pode voltar a ligá-los nas preferências de notificações.", en: "Done: you won't get these emails any more. You can turn them back on in notification preferences.", zh: "完成：您将不再收到这些邮件。可在通知偏好中重新开启。", fr: "C'est fait : vous ne recevrez plus ces e-mails. Vous pouvez les réactiver dans les préférences de notification." },
  "em.unsub.error": { pt: "Esta ligação não é válida. Desligue os emails nas preferências de notificações.", en: "This link isn't valid. Turn emails off in notification preferences.", zh: "此链接无效。请在通知偏好中关闭邮件。", fr: "Ce lien n'est pas valide. Désactivez les e-mails dans les préférences de notification." },
  "ls.np_email": { pt: "📧 Resumo diário por email", en: "📧 Daily email summary", zh: "📧 每日邮件摘要", fr: "📧 Résumé quotidien par e-mail" },
  "ls.np_email_hint": { pt: "Uma vez por dia, se tiver avisos por ler, enviamos um email com os mais recentes. Nada de publicidade de outras empresas.", en: "Once a day, if you have unread notices, we send one email with the latest ones. No advertising from other companies.", zh: "如果您有未读通知，我们每天最多发送一封包含最新通知的邮件。不含其他公司的广告。", fr: "Une fois par jour, si vous avez des avis non lus, nous envoyons un e-mail avec les plus récents. Aucune publicité d'autres entreprises." },
  "ls.np_push": { pt: "📱 Notificações no telemóvel", en: "📱 Phone notifications", zh: "📱 手机通知", fr: "📱 Notifications sur le téléphone" },
  "ls.np_push_hint": { pt: "Os avisos aparecem no ecrã do telemóvel onde tem a APP do Huambo Online com sessão iniciada, mesmo com a APP fechada.", en: "Alerts appear on the screen of the phone where you are signed in to the Huambo Online APP, even with the APP closed.", zh: "提醒会显示在已登录 Huambo Online APP 的手机屏幕上，即使 APP 已关闭。", fr: "Les alertes s'affichent sur l'écran du téléphone où vous êtes connecté à l'APP Huambo Online, même APP fermée." },
  "ls.np_interests": { pt: "✨ Novidades para si", en: "✨ New for you", zh: "✨ 为您推荐的新内容", fr: "✨ Nouveautés pour vous" },
  "ls.np_interests_hint": { pt: "Avisamos quando aparecem anúncios novos de que pode gostar, pelo que vê, pesquisa e guarda. A IA escolhe só os que combinam consigo; se nada combinar, não recebe aviso.", en: "We let you know when new listings you may like appear, based on what you view, search and save. AI picks only the ones that match you; if nothing matches, you get no notice.", zh: "根据您浏览、搜索和收藏的内容，出现您可能喜欢的新信息时我们会通知您。AI 只挑选符合您兴趣的信息；如果没有合适的，就不会通知。", fr: "Nous vous prévenons quand de nouvelles annonces qui pourraient vous plaire apparaissent, selon ce que vous consultez, recherchez et enregistrez. L'IA ne choisit que celles qui vous correspondent ; si rien ne correspond, vous ne recevez pas d'avis." },
