  "ai.bg.working": { pt: "A tirar o fundo…", en: "Removing the background…", zh: "正在去除背景…", fr: "Suppression du fond…" },
  "ai.bg.undo": { pt: "↩️ Desfazer", en: "↩️ Undo", zh: "↩️ 撤销", fr: "↩️ Annuler" },
  "ai.bg.style": { pt: "Fundo para as fotografias", en: "Background for the photos", zh: "照片背景", fr: "Fond des photos" },
  "ai.bg.hint": { pt: "Toque em «🪄 Fundo branco» numa fotografia: tiramos o fundo e pomos o artigo ao centro, num fundo limpo. Confira o resultado (pode desfazer).", en: "Tap “🪄 White background” on a photo: we remove the background and put the item in the middle, on a clean background. Check the result (you can undo).", zh: "在照片上点击“🪄 白色背景”：我们会去除背景，并把物品放在干净背景的中间。请检查效果（可以撤销）。", fr: "Touchez « 🪄 Fond blanc » sur une photo : nous retirons le fond et plaçons l'article au centre, sur un fond propre. Vérifiez le résultat (vous pouvez annuler)." },
