  "ai.fill.hint": { pt: "Junte uma fotografia e a IA propõe o título, a categoria e os dados. Reveja tudo antes de publicar.", en: "Add a photo and AI suggests the title, category and details. Review everything before posting.", zh: "添加一张照片，AI 会建议标题、类别和详情。发布前请检查所有内容。", fr: "Ajoutez une photo et l'IA suggère le titre, la catégorie et les détails. Relisez tout avant de publier." },
  "ai.fill.need_photo": { pt: "Junte primeiro uma fotografia do artigo.", en: "First add a photo of the item.", zh: "请先添加物品照片。", fr: "Ajoutez d'abord une photo de l'article." },
  "ai.fill.not_found": { pt: "A IA não reconheceu um artigo nesta fotografia. Preencha à mão.", en: "AI didn't recognise an item in this photo. Fill it in by hand.", zh: "AI 未能在照片中识别出物品。请手动填写。", fr: "L'IA n'a pas reconnu d'article sur cette photo. Remplissez à la main." },
  "ai.fill.done": { pt: "Preenchido a partir da fotografia. Reveja, junte o estado, os defeitos e o preço. Restam {n} hoje.", en: "Filled in from the photo. Review it and add the condition, any defects and the price. {n} left today.", zh: "已根据照片填写。请检查并补充状况、缺陷和价格。今天还剩 {n} 次。", fr: "Rempli à partir de la photo. Relisez et ajoutez l'état, les éventuels défauts et le prix. Il en reste {n} aujourd'hui." },
  "ai.price.hint": { pt: "💡 Anúncios parecidos: {low} a {high} (preço do meio {median}, {n} anúncios).", en: "💡 Similar listings: {low} to {high} (middle price {median}, {n} listings).", zh: "💡 类似信息：{low} 至 {high}（中间价 {median}，共 {n} 条）。", fr: "💡 Annonces similaires : de {low} à {high} (prix médian {median}, {n} annonces)." },
